      </div>

      {/* ── Dialogs ──────────────────────────────────────────────────────── */}

      {/* Kurs create/edit dialog */}
      <Dialog open={kursDialog.open} onOpenChange={o => setKursDialog(d => ({ ...d, open: o }))}>
