          <DialogFooter>
            <Button variant="outline" onClick={() => setDeleteKursId(null)}>Abbrechen</Button>
            <Button
              variant="destructive"
              disabled={saving}
              onClick={() => deleteKursId && handleDeleteKurs(deleteKursId)}
