   557→// ── Sub-components ─────────────────────────────────────────────────────────────
   558→
   559→function KpiCard({ icon, label, value, color }: {
   560→  icon: React.ReactNode;
   561→  label: string;
   562→  value: number | string;
   563→  color: 'indigo' | 'violet' | 'sky' | 'emerald';
   564→}) {
   565→  const colors = {
   566→    indigo: 'bg-indigo-50 text-indigo-600 dark:bg-indigo-950/30',
   567→    violet: 'bg-violet-50 text-violet-600 dark:bg-violet-950/30',
   568→    sky: 'bg-sky-50 text-sky-600 dark:bg-sky-950/30',
   569→    emerald: 'bg-emerald-50 text-emerald-600 dark:bg-emerald-950/30',
   570→  };
   571→  return (
   572→    <div className="rounded-2xl border border-border bg-card p-4">
   573→      <div className={`w-8 h-8 rounded-xl flex items-center justify-center mb-2 ${colors[color]}`}>
   574→        {icon}
   575→      </div>
   576→      <p className="text-2xl font-bold tracking-tight">{value}</p>
   577→      <p className="text-xs text-muted-foreground mt-0.5">{label}</p>
   578→    </div>
   579→  );
   580→}
   581→
   582→function InfoChip({ icon, label, value }: { icon: React.ReactNode; label: string; value: string }) {
   583→  return (
   584→    <div className="flex flex-col gap-0.5">
   585→      <p className="text-xs text-muted-foreground flex items-center gap-1">{icon} {label}</p>
   586→      <p className="text-sm font-medium truncate">{value}</p>
   587→    </div>
   588→  );
   589→}
   590→
   591→function AnmeldungDialog({ open, onClose, teilnehmer, saving, onSave }: {
   592→  open: boolean;
   593→  onClose: () => void;
   594→  teilnehmer: import('@/types/app').Teilnehmer[];
   595→  saving: boolean;
   596→  onSave: (form: AnmeldungFormData) => void;
   597→}) {
   598→  const today = new Date().toISOString().slice(0, 10);
   599→  const [form, setForm] = useState<AnmeldungFormData>({ teilnehmerId: 'none', anmeldedatum: today, bezahlt: false });
   600→
   601→  return (
   602→    <Dialog open={open} onOpenChange={o => !o && onClose()}>
   603→      <DialogContent className="max-w-sm">
   604→        <DialogHeader>
   605→          <DialogTitle>Teilnehmer anmelden</DialogTitle>
   606→        </DialogHeader>
   607→        <div className="space-y-4 py-1">
   608→          <div className="space-y-1.5">
   609→            <Label>Teilnehmer</Label>
   610→            <Select value={form.teilnehmerId} onValueChange={v => setForm(f => ({ ...f, teilnehmerId: v }))}>
   611→              <SelectTrigger>
   612→                <SelectValue placeholder="Auswählen..." />
   613→              </SelectTrigger>
   614→              <SelectContent>
   615→                <SelectItem value="none">— Auswählen —</SelectItem>
   616→                {teilnehmer.map(t => (
   617→                  <SelectItem key={t.record_id} value={t.record_id}>
   618→                    {t.fields.vorname} {t.fields.nachname}
   619→                  </SelectItem>
   620→                ))}
   621→              </SelectContent>
   622→            </Select>
   623→          </div>
   624→          <div className="space-y-1.5">
   625→            <Label>Anmeldedatum</Label>
   626→            <Input type="date" value={form.anmeldedatum} onChange={e => setForm(f => ({ ...f, anmeldedatum: e.target.value }))} />
   627→          </div>
   628→          <label className="flex items-center gap-2 cursor-pointer">
   629→            <input
   630→              type="checkbox"
   631→              className="rounded"
   632→              checked={form.bezahlt}
   633→              onChange={e => setForm(f => ({ ...f, bezahlt: e.target.checked }))}
   634→            />
   635→            <span className="text-sm">Bereits bezahlt</span>
   636→          </label>
   637→        </div>
   638→        <DialogFooter>
   639→          <Button variant="outline" onClick={onClose}>Abbrechen</Button>
   640→          <Button
   641→            disabled={saving || form.teilnehmerId === 'none'}
   642→            onClick={() => onSave(form)}
   643→          >
   644→            {saving ? 'Speichern...' : 'Anmelden'}
   645→          </Button>
   646→        </DialogFooter>
   647→      </DialogContent>
   648→    </Dialog>
   649→  );
   650→}
   651→
   652→function DashboardSkeleton() {
   653→  return (
   654→    <div className="space-y-6">
   655→      <div className="flex items-center justify-between">
   656→        <Skeleton className="h-8 w-48" />
   657→        <Skeleton className="h-9 w-36" />
   658→      </div>
   659→      <div className="grid grid-cols-2 lg:grid-cols-4 gap-3">
   660→        {[...Array(4)].map((_, i) => <Skeleton key={i} className="h-24 rounded-2xl" />)}
   661→      </div>
   662→      <Skeleton className="h-64 rounded-2xl" />
   663→    </div>
   664→  );
   665→}
   666→
   667→function DashboardError({ error, onRetry }: { error: Error; onRetry: () => void }) {
   668→  return (
   669→    <div className="flex flex-col items-center justify-center py-24 gap-4">
   670→      <div className="w-12 h-12 rounded-2xl bg-destructive/10 flex items-center justify-center">
   671→        <AlertCircle size={22} className="text-destructive" />
   672→      </div>
   673→      <div className="text-center">
   674→        <h3 className="font-semibold text-foreground mb-1">Fehler beim Laden</h3>
   675→        <p className="text-sm text-muted-foreground max-w-xs">{error.message}</p>
   676→      </div>
   677→      <Button variant="outline" size="sm" onClick={onRetry}>Erneut versuchen</Button>
